pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address initialCeo) public {
        vm.assume(caller != initialCeo);
        // Ensure initialCeo is the one who initializes ceoAddress via DrugDealer in the reference
        vm.prank(initialCeo);
        c.DrugDealer();
        // Now a non-ceo caller attempts to call DrugDealer
        vm.prank(caller);
        bool reverted;
        try c.DrugDealer() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // In the correct contract, it must have reverted; in the mutant it succeeds and changes ceoAddress to caller.
        // By additionally checking that ceoAddress is unchanged from the initialCeo, we ensure the mutant shows a difference.
        assertTrue(reverted && c.ceoAddress() == initialCeo);
    }
}

