contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint8 v, bytes32 r, bytes32 s) public payable {
        require(caller != address(0));
        bool reverted;
        bytes memory data = abi.encodeWithSignature("DrugDealer()");
        bytes32 hash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", keccak256(data)));
        address signer = ecrecover(hash, v, r, s);
        require(signer == caller);
        (bool success, ) = address(c).call(abi.encodePacked(data, caller));
        reverted = !success;
        assert(reverted == true);
    }
    receive() external payable {}
}

