        try c.DrugDealer() { } catch { reverted = true; }
        assert(!reverted ? c.ceoAddress() == 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26 : caller == address(0));
    }
    fallback() external payable {}
    receive() external payable {}
